<?php
require __DIR__.'/config.php';$me=require_auth();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||$id<1){http_response_code(404);exit('Account not found.');}
$s=db()->prepare('SELECT a.account_id,a.account_number,a.account_title,a.balance,a.currency,a.status,a.opening_date,a.closing_date,t.type_name,t.minimum_balance,t.interest_rate,b.branch_name FROM account_holders mine JOIN accounts a ON a.account_id=mine.account_id JOIN account_types t ON t.account_type_id=a.account_type_id JOIN branches b ON b.branch_id=a.branch_id WHERE mine.customer_id=? AND a.account_id=?');$s->execute([$me['customer_id'],$id]);$account=$s->fetch();if(!$account){http_response_code(404);exit('Account not found.');}
$s=db()->prepare('SELECT c.full_name,h.holder_role,h.operating_mode FROM account_holders h JOIN customers c ON c.customer_id=h.customer_id WHERE h.account_id=? ORDER BY h.holder_role DESC,c.full_name');$s->execute([$id]);$holders=$s->fetchAll();$s=db()->prepare('SELECT full_name,relationship,date_of_birth,share_percentage FROM nominees WHERE account_id=? ORDER BY nominee_id');$s->execute([$id]);$nominees=$s->fetchAll();$s=db()->prepare('SELECT transaction_id,reference_number,transaction_type,amount,balance_after,status,created_at FROM transactions WHERE account_id=? ORDER BY created_at DESC,transaction_id DESC LIMIT 5');$s->execute([$id]);$tx=$s->fetchAll();render_start('Account details');?><section class="page-heading"><div class="eyebrow dark">Account details</div><h1><?=e($account['account_title'])?></h1><p><?=e($account['type_name'])?> · <?=e($account['account_number'])?></p></section><section class="stats"><article class="stat"><span>Available balance</span><strong>BDT <?=e(number_format((float)$account['balance'],2))?></strong></article><article class="stat"><span>Status</span><strong><?=e(ucfirst($account['status']))?></strong></article><article class="stat"><span>Minimum balance</span><strong>BDT <?=e(number_format((float)$account['minimum_balance'],2))?></strong></article><article class="stat"><span>Interest rate</span><strong><?=e(number_format((float)$account['interest_rate'],2))?>%</strong></article></section><section class="detail-grid"><article class="detail-card"><h2>Account information</h2><dl><dt>Account number</dt><dd><?=e($account['account_number'])?></dd><dt>Branch</dt><dd><?=e($account['branch_name'])?></dd><dt>Opened</dt><dd><?=e($account['opening_date'])?></dd><dt>Holder mode</dt><dd><?=e(ucwords(str_replace('_',' ',$holders[0]['operating_mode']??'')))?></dd><?php if($account['closing_date']):?><dt>Closed</dt><dd><?=e($account['closing_date'])?></dd><?php endif;?></dl></article><article class="detail-card"><h2>Account holders</h2><?php if($holders):?><ul class="holder-list"><?php foreach($holders as $h):?><li><span><?=e($h['full_name'])?></span><span class="badge"><?=e(ucfirst($h['holder_role']))?></span></li><?php endforeach;?></ul><?php else:?><p class="muted">Holder details unavailable.</p><?php endif;?></article></section><section class="detail-card"><h2>Nominees</h2><?php if($nominees):?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Relationship</th><th>Date of birth</th><th>Share</th></tr></thead><tbody><?php foreach($nominees as $n):?><tr><td><?=e($n['full_name'])?></td><td><?=e($n['relationship'])?></td><td><?=e($n['date_of_birth']??'—')?></td><td><?=e(number_format((float)$n['share_percentage'],2))?>%</td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No nominee is recorded for this account.</p><?php endif;?></section><div class="section-heading"><h2>Mini statement</h2><a href="<?=e(url('activity.php?account_id='.$id))?>">Full statement →</a></div><?php if($tx):?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Reference</th><th>Type</th><th>Status</th><th>Amount</th><th>Balance after</th></tr></thead><tbody><?php foreach($tx as $t):?><tr><td><?=e($t['created_at'])?></td><td><a href="<?=e(url('transaction.php?id='.(int)$t['transaction_id']))?>"><?=e($t['reference_number'])?></a></td><td><?=e(ucwords(str_replace('_',' ',$t['transaction_type'])))?></td><td><?=e(ucfirst($t['status']))?></td><td>BDT <?=e(number_format((float)$t['amount'],2))?></td><td>BDT <?=e(number_format((float)$t['balance_after'],2))?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No transactions for this account.</div><?php endif;?><?php render_end();?>
